Object.entries(PROFESSIONAL_TOOL_GUIDE_ADDITIONS).forEach(([toolId, addition]) => {
  const tool = WORKSHOP_TOOLS[toolId];
  if (!tool) return;
  if (addition.description) tool.description = addition.description;
  if (addition.detail) tool.detail = addition.detail;
  if (!tool.guide) tool.guide = { overview: tool.detail || tool.description || '', sections: [] };
  tool.guide.sections = [...(tool.guide.sections || []), ...(addition.sections || [])];
  tool.guide.references = [...new Set([...(tool.guide.references || []), ...(addition.references || [])])];
});


