        `良好な結果だけでなく、刃折れ、傷、変形、発熱、石の緩み、寸法超過などの失敗条件も残します。記録を工具交換、材料ロット、修理、校正履歴と結び付けると、個人差と設備劣化を切り分け、次回の見積り・納期・品質基準へ反映できます。`
